import{_ as a,o as t,c as s,a6 as n}from"./chunks/framework.BBdhcoHf.js";const b=JSON.parse('{"title":"Protocols","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/index.md","filePath":"protocols/index.md","lastUpdated":1771970963000}'),r={name:"protocols/index.md"};function i(o,e,d,p,c,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols.md for this page in Markdown format</div><h1 id="protocols" tabindex="-1">Protocols <a class="header-anchor" href="#protocols" aria-label="Permalink to “Protocols”">​</a></h1><p>Sideband is a layered communication stack for browser-to-daemon communication, designed to work reliably behind NAT with end-to-end encryption.</p><blockquote><p>These specifications are implementation-neutral. You may implement them in any language or runtime, including proprietary systems, under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> terms. The wire format uses standard binary encoding (little-endian, length-prefixed) and widely supported cryptographic primitives (ChaCha20-Poly1305, X25519, Ed25519). The reference implementation and SDK are TypeScript.</p></blockquote><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p><strong>Start here</strong>: <a href="./stack">Protocol Architecture</a> defines layering, frame wrapping rules, and dependency invariants. All specifications below must be consistent with the architecture document.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌───────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Application / SDK                                 │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ RPC (semantic envelopes inside MessageFrame.data) │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ SBP (application framing, routing, correlation)   │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Session: SBRP (relay E2EE) or SBDP (direct P2P)   │</span></span>
<span class="line"><span>├───────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Transport (WebSocket, WebRTC, etc.)               │</span></span>
<span class="line"><span>└───────────────────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Layer</th><th>Protocol</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td>App Framing</td><td>SBP</td><td>v1</td><td>Framing, multiplexing, message routing</td></tr><tr><td>Relay Session</td><td>SBRP</td><td>Draft</td><td>E2EE sessions via relay server</td></tr><tr><td>Direct Session</td><td>SBDP</td><td>Design</td><td>P2P encryption (future)</td></tr><tr><td>Semantic</td><td>RPC</td><td>v1</td><td>Typed request/response patterns</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>RPC envelopes live inside <code>MessageFrame.data</code>. Session layers (SBRP/SBDP) encrypt entire SBP frames; they never inspect RPC content. See <a href="./stack">architecture</a> for wrapping rules.</p></div><h2 id="sbp-sideband-protocol" tabindex="-1">SBP (Sideband Protocol) <a class="header-anchor" href="#sbp-sideband-protocol" aria-label="Permalink to “SBP (Sideband Protocol)”">​</a></h2><p>Topology-agnostic framing used by all session layers. Defines frame types, message routing, and wire format.</p><p><a href="./sbp/">Read the SBP specification →</a></p><h2 id="sbrp-sideband-relay-protocol" tabindex="-1">SBRP (Sideband Relay Protocol) <a class="header-anchor" href="#sbrp-sideband-relay-protocol" aria-label="Permalink to “SBRP (Sideband Relay Protocol)”">​</a></h2><p>Default transport: secure, relay-based sessions with E2EE. The relay never sees plaintext.</p><p><a href="./sbrp/">Read the SBRP specification →</a></p><h2 id="sbdp-sideband-direct-protocol" tabindex="-1">SBDP (Sideband Direct Protocol) <a class="header-anchor" href="#sbdp-sideband-direct-protocol" aria-label="Permalink to “SBDP (Sideband Direct Protocol)”">​</a></h2><p>Future: direct P2P when both peers can establish a connection without relay.</p><p><a href="./sbdp/">Read the SBDP specification →</a></p><h2 id="rpc" tabindex="-1">RPC <a class="header-anchor" href="#rpc" aria-label="Permalink to “RPC”">​</a></h2><p>Typed request/response/notification semantics inside SBP message frames.</p><p><a href="./rpc/">Read the RPC specification →</a></p>`,21)])])}const m=a(r,[["render",i]]);export{b as __pageData,m as default};
